<?php
require_once dirname(__DIR__) . '/_common.php';$id=isset($_GET['id'])?(int)$_GET['id']:0;$stmt=$pdo->prepare('SELECT l.*,a.nama AS anggota_nama,a.kelas,a.email,k.nama AS kategori FROM laporan l JOIN anggota a ON a.id=l.anggota_id LEFT JOIN kategori_laporan k ON k.id=l.kategori_id WHERE l.id=?');$stmt->execute([$id]);$item=$stmt->fetch();if(!$item){osis_set_flash('error','Laporan tidak ditemukan.');osis_redirect('admin/laporan/index.php');}$pageTitle='Detail laporan';$error='';$statuses=['baru','diproses','selesai','ditolak'];
if(osis_admin_is_post()){osis_verify_csrf();$status=isset($_POST['status'])?(string)$_POST['status']:'baru';$balasan=osis_post_string('balasan',8000);if(!in_array($status,$statuses,true)){$error='Status tidak valid.';}else{try{$stmt=$pdo->prepare('UPDATE laporan SET status=?,balasan=?,ditangani_oleh=? WHERE id=?');$stmt->execute([$status,$balasan?:null,osis_current_user()['id'],$id]);osis_log_activity('Memperbarui status laporan: '.$item['judul'].' → '.$status);osis_set_flash('success','Status dan tanggapan laporan berhasil disimpan.');osis_redirect('admin/laporan/detail.php?id='.$id);}catch(PDOException $exception){$error='Laporan gagal diperbarui.';}}}
osis_admin_page_start($pageTitle);
?>
<div class="admin-form-wrap wide-form"><a class="back-link" href="<?=osis_e(osis_url('admin/laporan/index.php'))?>">← Semua laporan</a><?php if($error):?><div class="alert alert-error"><?=osis_e($error)?></div><?php endif;?><div class="report-detail-grid"><article class="admin-panel report-detail-panel"><div class="badge-line"><span class="badge badge-status badge-<?=osis_e($item['status'])?>"><?=osis_e(ucfirst($item['status']))?></span><span class="mini-date"><?=osis_e(osis_format_date($item['created_at'],true))?></span></div><h2><?=osis_e($item['judul'])?></h2><div class="report-author">Dikirim oleh <strong><?=osis_e($item['anggota_nama'])?></strong> · <?=osis_e($item['kelas']?:'Anggota OSIS')?> · <?=osis_e($item['kategori']?:'Aspirasi umum')?></div><div class="report-content"><?=nl2br(osis_e($item['isi']))?></div><?php if($item['file']):?><a class="attachment-link" href="<?=osis_e(osis_image_url($item['file']))?>" target="_blank" rel="noopener"><img src="<?=osis_e(osis_image_url($item['file']))?>" alt="Lampiran laporan"><span>Lihat lampiran ↗</span></a><?php endif;?></article><aside class="admin-panel report-response-panel"><span class="eyebrow">TINDAK LANJUT</span><h2>Perbarui laporan</h2><form method="post"><?=osis_csrf_input()?><label for="status">Status laporan</label><select id="status" name="status"><?php foreach($statuses as $status):?><option value="<?=osis_e($status)?>" <?=isset($_POST['status'])?($_POST['status']===$status?'selected':''):($item['status']===$status?'selected':'')?>><?=osis_e(ucfirst($status))?></option><?php endforeach;?></select><label for="balasan">Tanggapan untuk anggota</label><textarea id="balasan" name="balasan" rows="8" placeholder="Tulis tanggapan atau tindak lanjut..."><?=osis_e(isset($_POST['balasan'])?$_POST['balasan']:$item['balasan'])?></textarea><button class="button button-primary button-full" type="submit">Simpan pembaruan <span>↗</span></button></form><p class="muted-copy">Anggota dapat melihat tanggapan ini di halaman Laporan Saya.</p></aside></div></div>
<?php osis_admin_page_end(); ?>
